\label{lem:basicfacts} 
Let $\Gamma$ be a set of labelled formulas, then $\Gamma \vdash \alpha \mathbin: \varphi$ iff
$\Gamma,\alpha \mathbin:\lnot \varphi \vdash \alpha \mathbin: \bot$.

\label{prop:max}
    If $\Gamma$ is consistent then so is either $\Gamma,\alpha \mathbin: \varphi$ or
    $\Gamma, \alpha \mathbin: \lnot \varphi$.

Let $\Gamma$ be a set of labelled formulas and $\Gamma'$ be the result of
renaming the atomic labels $p_i$ by $p_{2i}$. Then 
\begin{enumerate}
    \item $\Gamma$ is consistent iff $\Gamma'$ is, and
    \item $\Gamma$ is satisfiable iff $\Gamma'$ is.
\end{enumerate}

Let $\mathcal{X}$ be a class of Boolean algebras, then $\Delta \vDash_\mathcal
{X} \psi$ if for all $B \in \mathcal{X}$ and all homomorphisms $H:\ensuremath{\mathtt{Fm}} \to {\mathcal P}
B$: $$\bigcap_{\varphi \in\Delta} H(\varphi) \subseteq H(\psi).$$

\label{lemma:trivial}
Let $\mathbbm 1$ denote the trivial one-element Boolean algebra and $\mathbbm 2$ the
two-element Boolean algebra.
    \begin{enumerate}
        \item\label{ett:label} $\vDash_B \mathord{\vphantom{\bot}\mathpalette\ibot@\relax} \text{ iff } B=\mathbbm 1$
        \item $\vDash_B \mathord{\vphantom{\bot}\mathpalette\ibot@\relax} \lor \mathord{\vphantom{\lnot}\mathpalette\ilnot@\relax}\mathord{\vphantom{\bot}\mathpalette\ibot@\relax} \text{ iff } B \in \{\mathbbm 1,\mathbbm 2\}$
        \item If a formula $\varphi$ contains no propositional variables then 
        $$\nvDash_B \varphi \text{ iff } \vDash_B \lnot\mathord{\vphantom{\bot}\mathpalette\ibot@\relax} \lor (\mathord{\vphantom{\bot}\mathpalette\ibot@\relax} \mathrel{\vphantom{\land}\mathpalette\iland@\relax} \lnot \varphi).$$
    \end{enumerate}

The \emph{external implication} is the connective defined by
	\begin{equation*}
		\varphi \to \psi := \lnot \varphi \lor \psi.
	\end{equation*}

\label{th:deduction}
	For all $\Delta \cup \set{\varphi,\psi}\subseteq\ensuremath{\mathtt{Fm}}$
	$$\Delta, \varphi  \vDash \psi \quad \text{iff} \quad \Delta \vDash \varphi \to \psi.$$

\label{prop:S5_fragment}
	A formula built up from atoms using $\bot,\lnot, \land, \lor,\to,$ and $\Box$ is valid
	in LTP iff it is valid in the modal logic S5.

\label{strict_negation}
	In LTP we define the unary operation $\mathord{{\sim}}$ by $$ \mathord{{\sim}} \varphi= \lnot\mathop{\uparrow}(
	\mathop{\downarrow} \varphi\land \mathord{\text{NB}} ).$$

\label{slnot_form_to_subset}
	For every Boolean algebra $B$, every homomorphism $H:\ensuremath{\mathtt{Fm}} \to {\mathcal P} B$, and
	every formula $\varphi\in\ensuremath{\mathtt{Fm}}$ we have $$ H(\mathord{{\sim}} \varphi) = \mathord{{\sim}} H(\varphi).$$

\label{prop_strict_neg}
	\begin{enumerate}
		\item $\vDash P \to \mathord{{\sim}} \mathord{{\sim}} P$ 
		\item $\nvDash \mathord{{\sim}} \mathord{{\sim}} P \to P $ 
		\item $\vDash \mathord{{\sim}}  \mathord{{\sim}} \mathord{{\sim}}  P \rightarrow \mathord{{\sim}} P$ 

		\item $\nvDash P \mathrel{\vphantom{\lor}\mathpalette\ilor@\relax} \mathord{{\sim}} P$

	\end{enumerate}

Let $H_V$ denote \textit{the valuation homomorphism}, i.e., the unique homomorphism $H_V : \ensuremath{\mathtt{Fm}} \to {\mathcal P}{\mathcal P}
2^\mathbb{N}$ such that
\[ 
H_V(P_i) = \set { X\in {\mathcal P} 2^{\mathbb{N}} | \text{ for all } s\in X, s(i)= 1 }
= {\mathcal P} \set{ s\in 2^{\mathbb{N}} | s(i) = 1}.
\]
